import Foundation

/// Titles found in a Claude Code transcript (.jsonl).
public struct TranscriptTitles: Equatable, Sendable {
    /// Set with `/rename`; stored as `{"type":"custom-title","customTitle":"…"}`.
    public var customTitle: String?
    /// Generated by Claude; stored as `{"type":"ai-title","aiTitle":"…"}`.
    public var aiTitle: String?

    public init(customTitle: String? = nil, aiTitle: String? = nil) {
        self.customTitle = customTitle
        self.aiTitle = aiTitle
    }
}

public enum TranscriptReader {
    /// Transcripts can exceed 100 MB, so only the tail is read; title records are re-appended
    /// as the session goes on, and the head covers an aiTitle written once at the start.
    public static let tailBytes = 2 * 1024 * 1024
    public static let headBytes = 256 * 1024

    /// The last customTitle and aiTitle in a chunk of JSON lines. Searches bytes backwards for the
    /// key and parses only that line, so megabytes of conversation are never decoded.
    public static func parse(_ data: Data) -> TranscriptTitles {
        TranscriptTitles(customTitle: lastValue(of: "customTitle", in: data), aiTitle: lastValue(of: "aiTitle", in: data))
    }

    /// Reads titles from bytes appended after `offset` (or the last `tailBytes` when that is
    /// further back), walking backwards in small chunks and stopping once both titles are found.
    /// Returns the titles in that range and the file size it read up to.
    public static func read(_ url: URL, after offset: UInt64 = 0, chunkSize: Int = 256 * 1024) -> (titles: TranscriptTitles, size: UInt64) {
        guard let handle = try? FileHandle(forReadingFrom: url) else { return (TranscriptTitles(), 0) }
        defer { try? handle.close() }
        let size = (try? handle.seekToEnd()) ?? 0
        let floor = max(offset, size > UInt64(tailBytes) ? size - UInt64(tailBytes) : 0)
        var titles = TranscriptTitles()
        var upper = size
        var carry = Data()  // the partial first line of the chunk read before, completed by the next one
        while upper > floor, titles.customTitle == nil || titles.aiTitle == nil {
            autoreleasepool {
                let lower = upper - min(UInt64(chunkSize), upper - floor)
                try? handle.seek(toOffset: lower)
                var chunk = (try? handle.read(upToCount: Int(upper - lower))) ?? Data()
                chunk.append(carry)
                var body = chunk[...]
                carry = Data()
                if lower > floor {
                    // Everything before the first newline may continue in the previous chunk; keep it for later
                    // (dropped past 4 MB: such a line is conversation text, not a title record).
                    let newline = chunk.firstIndex(of: 0x0a) ?? chunk.endIndex
                    if newline - chunk.startIndex < 4 * 1024 * 1024 { carry = Data(chunk[..<newline]) }
                    body = newline < chunk.endIndex ? chunk[(newline + 1)...] : chunk[chunk.endIndex...]
                }
                let found = parse(Data(body))
                titles.customTitle = titles.customTitle ?? found.customTitle
                titles.aiTitle = titles.aiTitle ?? found.aiTitle
                upper = lower
            }
        }
        if titles.aiTitle == nil, offset == 0, floor > 0 {
            try? handle.seek(toOffset: 0)
            titles.aiTitle = autoreleasepool { parse((try? handle.read(upToCount: headBytes)) ?? Data()).aiTitle }
        }
        return (titles, size)
    }

    private static func lastValue(of key: String, in data: Data) -> String? {
        let marker = Data("\"\(key)\":\"".utf8)
        var end = data.endIndex
        while let found = data.range(of: marker, options: .backwards, in: data.startIndex..<end) {
            let lineStart = data[..<found.lowerBound].lastIndex(of: 0x0a).map { $0 + 1 } ?? data.startIndex
            let lineEnd = data[found.upperBound...].firstIndex(of: 0x0a) ?? data.endIndex
            if let object = try? JSONSerialization.jsonObject(with: data[lineStart..<lineEnd]) as? [String: Any],
               let value = clean(object[key]) {
                return value
            }
            end = found.lowerBound
        }
        return nil
    }

    /// Where Claude Code keeps the transcript: ~/.claude/projects/<cwd with non-alphanumerics as "-">/<id>.jsonl.
    public static func path(home: URL, cwd: String, sessionId: String) -> URL {
        let folder = String(cwd.unicodeScalars.map { CharacterSet.alphanumerics.contains($0) && $0.isASCII ? Character($0) : "-" })
        return home.appendingPathComponent(".claude/projects/\(folder)/\(sessionId).jsonl")
    }

    private static func clean(_ value: Any?) -> String? {
        guard let text = value as? String else { return nil }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : String(trimmed.prefix(120))
    }
}

public enum CmuxTree {
    /// surface id → tab title, from `cmux tree --all --json --id-format uuids`.
    public static func surfaceTitles(from data: Data) -> [String: String] {
        guard let root = try? JSONSerialization.jsonObject(with: data) else { return [:] }
        var titles: [String: String] = [:]
        func walk(_ node: Any, inSurfaces: Bool) {
            if let object = node as? [String: Any] {
                if inSurfaces, let id = object["id"] as? String, let title = object["title"] as? String {
                    let cleaned = cleanTitle(title)
                    if !cleaned.isEmpty { titles[id.uppercased()] = cleaned }
                }
                for (key, value) in object { walk(value, inSurfaces: key == "surfaces") }
            } else if let array = node as? [Any] {
                for element in array { walk(element, inSurfaces: inSurfaces) }
            }
        }
        walk(root, inSurfaces: false)
        return titles
    }

    /// Terminal titles set by Claude Code start with a status glyph ("✳ name", braille spinners); drop it.
    public static func cleanTitle(_ title: String) -> String {
        var scalars = Array(title.unicodeScalars)
        while let first = scalars.first,
              first.properties.generalCategory == .otherSymbol || (0x2800...0x28FF).contains(first.value)
                || CharacterSet.whitespaces.contains(first) {
            scalars.removeFirst()
        }
        var view = String.UnicodeScalarView()
        view.append(contentsOf: scalars)
        return String(view).trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

/// Prefer conversation names, then cmux, AI, or hook titles in that order.
/// Title reads are cached; call from a single serial queue.
public final class SessionNamer: @unchecked Sendable {
    public var transcriptInterval: TimeInterval = 30
    public var cmuxInterval: TimeInterval = 20
    public var codexInterval: TimeInterval = 30
    /// Runs the cmux CLI and returns stdout; replaceable in tests.
    public var runCmux: (String, [String]) -> Data? = SessionNamer.run

    private let home: URL
    private var transcripts: [String: (checked: Date, size: UInt64, titles: TranscriptTitles)] = [:]
    private var cmuxTitles: [String: String] = [:]
    private var cmuxChecked: Date?
    private var codexTitles: [String: String] = [:]
    private var codexChecked: Date?

    public init(home: URL) {
        self.home = home
    }

    /// session id (AgentSession.id) → friendly name, for sessions that have one.
    public func names(for sessions: [AgentSession], records: [HookRecord], now: Date = Date()) -> [String: String] {
        refreshCmux(for: sessions, now: now)
        refreshCodex(for: sessions, now: now)
        var names: [String: String] = [:]
        var used = Set<String>()
        for session in sessions {
            let record = SessionMerger.matchingRecord(for: session, records: records, sessions: sessions)
            var titles = TranscriptTitles()
            if session.provider == .claude, let url = transcriptURL(for: session, record: record) {
                used.insert(url.path)
                titles = transcriptTitles(url, now: now)
            }
            let cmuxTitle = session.cmux.flatMap { cmuxTitles[$0.surfaceId.uppercased()] }
            let codexID = record.flatMap { $0.sessionId.isEmpty ? nil : $0.sessionId }
                ?? session.sessionId ?? session.launchSessionId
            let codexTitle = session.provider == .codex ? codexID.flatMap { codexTitles[$0.lowercased()] } : nil
            if let name = codexTitle ?? titles.customTitle ?? cmuxTitle ?? titles.aiTitle ?? record?.title {
                names[session.id] = name
            }
        }
        transcripts = transcripts.filter { used.contains($0.key) }
        return names
    }

    private func transcriptURL(for session: AgentSession, record: HookRecord?) -> URL? {
        if let path = record?.transcriptPath { return URL(fileURLWithPath: path) }
        let id = record.flatMap { $0.sessionId.isEmpty ? nil : $0.sessionId } ?? session.launchSessionId
        guard let id, UUID(uuidString: id) != nil else { return nil }
        return TranscriptReader.path(home: home, cwd: session.cwd, sessionId: id)
    }

    /// Re-checked at most every `transcriptInterval`; only bytes appended since the last read are scanned.
    private func transcriptTitles(_ url: URL, now: Date) -> TranscriptTitles {
        let cached = transcripts[url.path]
        if let cached, now.timeIntervalSince(cached.checked) < transcriptInterval { return cached.titles }
        guard let size = (try? FileManager.default.attributesOfItem(atPath: url.path))?[.size] as? NSNumber else {
            return TranscriptTitles()
        }
        if let cached, cached.size == size.uint64Value {
            transcripts[url.path]?.checked = now
            return cached.titles
        }
        let grew = cached.map { size.uint64Value > $0.size } ?? false
        let read = TranscriptReader.read(url, after: grew ? cached!.size : 0)
        var titles = read.titles
        if grew, let old = cached?.titles {
            titles.customTitle = titles.customTitle ?? old.customTitle
            titles.aiTitle = titles.aiTitle ?? old.aiTitle
        }
        transcripts[url.path] = (now, read.size, titles)
        return titles
    }

    private func refreshCodex(for sessions: [AgentSession], now: Date) {
        guard sessions.contains(where: { $0.provider == .codex }) else {
            codexTitles = [:]
            codexChecked = nil
            return
        }
        if let checked = codexChecked, now.timeIntervalSince(checked) < codexInterval { return }
        codexChecked = now
        let url = home.appendingPathComponent(".codex/session_index.jsonl")
        let data = (try? Data(contentsOf: url, options: .mappedIfSafe)) ?? Data()
        codexTitles = CodexSessionIndex.titles(in: data)
    }

    private func refreshCmux(for sessions: [AgentSession], now: Date) {
        guard let cli = sessions.lazy.compactMap({ $0.cmux }).first.map({ $0.cli ?? CmuxControl.defaultCLI }) else {
            cmuxTitles = [:]
            return
        }
        if let checked = cmuxChecked, now.timeIntervalSince(checked) < cmuxInterval { return }
        cmuxChecked = now
        if let data = runCmux(cli, ["tree", "--all", "--json", "--id-format", "uuids"]) {
            cmuxTitles = CmuxTree.surfaceTitles(from: data)
        }
    }

    public static func run(_ executable: String, _ arguments: [String]) -> Data? {
        guard FileManager.default.isExecutableFile(atPath: executable) else { return nil }
        let process = Process()
        process.executableURL = URL(fileURLWithPath: executable)
        process.arguments = arguments
        let output = Pipe()
        process.standardOutput = output
        process.standardError = FileHandle.nullDevice
        do {
            try process.run()
        } catch {
            return nil
        }
        let data = output.fileHandleForReading.readDataToEndOfFile()
        process.waitUntilExit()
        return process.terminationStatus == 0 ? data : nil
    }
}

public enum CmuxControl {
    public static let defaultCLI = "/Applications/cmux.app/Contents/Resources/bin/cmux"
    public static let bundleIdentifier = "com.cmuxterm.app"

    /// Selects the session's workspace and focuses its tab. Returns false when cmux refused.
    @discardableResult
    public static func focus(_ location: CmuxLocation, run: (String, [String]) -> Data? = SessionNamer.run) -> Bool {
        let cli = location.cli ?? defaultCLI
        guard run(cli, ["select-workspace", "--workspace", location.workspaceId]) != nil else { return false }
        return run(cli, ["focus-panel", "--panel", location.surfaceId, "--workspace", location.workspaceId]) != nil
    }
}
